步骤1：准备表结构数据​ 假设已有database_schema.json，格式如下： { "tables": [ { "name": "sales", "columns": [ {"name": "id", "type": "int", "description": "销售记录ID"}, {"name": "product_id", "type": "int", "description": "关联products表"}, {"name": "sale_date", "type": "date", "description": "销售日期"}, {"name": "quantity", "type": "int", "description": "销售数量"} ], "description": "存储所有销售记录" }, { "name": "products", "columns": [ {"name": "id", "type": "int", "description": "产品ID"}, {"name": "name", "type": "varchar(255)", "description": "产品名称"}, {"name": "category", "type": "varchar(100)", "description": "产品类别"} ], "description": "存储产品主数据" } ] } 步骤2：向量化存储表结构​ import json import numpy as np import faiss from openai import OpenAI from tenacity import retry, stop_after_attempt, wait_exponential # 初始化 client = OpenAI(api_key="your_api_key") index = None # FAISS索引 schema_data = [] # 原始数据缓存 class SchemaVectorizer: def __init__(self): self.dim = 1536 # text-embedding-3-small维度 self.model = "text-embedding-3-small" @retry(stop=stop_after_attempt(3), wait=wait_exponential(multiplier=1, min=4, max=10)) def get_embedding(self, text): response = client.embeddings.create( input=[text], model=self.model ) return response.data[0].embedding def load_schema(self, json_path): """加载并向量化表结构""" with open(json_path) as f: data = json.load(f) global schema_data schema_data = data["tables"] # 生成描述文本 texts = [] for table in schema_data: desc = f"表名：{table['name']}，描述：{table['description']}。包含字段：" desc += "，".join([f"{col['name']}（{col['type']}）：{col['description']}" for col in table["columns"]]) texts.append(desc) # 向量化 embeddings = [self.get_embedding(text) for text in texts] embeddings = np.array(embeddings).astype('float32') # 构建FAISS索引 global index index = faiss.IndexFlatL2(self.dim) index.add(embeddings) faiss.write_index(index, "schema_index.faiss") # 初始化向量库 vectorizer = SchemaVectorizer() vectorizer.load_schema("database_schema.json") 步骤3：自然语言查询处理​ class QueryProcessor: def __init__(self): self.system_prompt = """你是一个数据库专家，根据用户问题识别需要查询的表结构。 输出格式： ```json { "tables": ["表名1", "表名2"], "reason": "选择这些表的理由", "query_hint": "建议的SQL查询片段" } ```""" def retrieve_relevant_tables(self, query): # 向量化查询 query_embedding = vectorizer.get_embedding(query) query_embedding = np.array([query_embedding]).astype('float32') # FAISS搜索 k = 3 # 返回top3相关表 distances, indices = index.search(query_embedding, k) # 获取相关表信息 results = [] for idx in indices[0]: if idx >= 0: # 有效索引 results.append(schema_data[idx]) return results def generate_sql_advice(self, query, tables): # 构建ChatGPT提示 tables_str = "
".join([f"## {t['name']}
- 描述：{t['description']}
" + "
".join([f" - {col['name']}: {col['description']}" for col in t["columns"]]) for t in tables]) user_prompt = f"""用户问题：“{query}” 相关表结构： {tables_str} 请回答： 1. 需要查询哪些字段？ 2. 需要哪些关联条件？ 3. 需要什么过滤条件？""" response = client.chat.completions.create( model="gpt-3.5-turbo", messages=[ {"role": "system", "content": self.system_prompt}, {"role": "user", "content": user_prompt} ], temperature=0.3, response_format={"type": "json_object"} ) return json.loads(response.choices[0].message.content) # 使用示例 processor = QueryProcessor() user_query = "2024年第三季度的乐高积木销售信息统计" relevant_tables = processor.retrieve_relevant_tables(user_query) advice = processor.generate_sql_advice(user_query, relevant_tables) print(advice) 步骤4：执行最终查询​ import sqlalchemy from sqlalchemy import create_engine class SQLExecutor: def __init__(self, db_url): self.engine = create_engine(db_url) def execute(self, sql): with self.engine.connect() as conn: result = conn.execute(sqlalchemy.text(sql)) return [dict(row) for row in result.mappings()] def build_final_query(advice): """根据建议构建完整SQL（示例逻辑）""" tables = advice["tables"] if len(tables) == 1: from_clause = tables[0] else: from_clause = " JOIN ".join(tables) return f""" SELECT * FROM {from_clause} WHERE 1=1 {'AND category = "乐高积木"' if 'products' in tables else ''} {'AND sale_date BETWEEN "2024-07-01" AND "2024-09-30"' if 'sales' in tables else ''} """ # 执行流程 db_url = "postgresql://user:pass@localhost:5432/mydb" executor = SQLExecutor(db_url) final_sql = build_final_query(advice) results = executor.execute(final_sql) # 结果格式化输出 from tabulate import tabulate print(tabulate(results, headers="keys", tablefmt="grid"))

